static s32 ixgbe_validate_link_ready ( struct ixgbe_hw * hw ) { u32 timeout ; u16 an_reg ; for ( timeout = 0 ; timeout < IXGBE_VALIDATE_LINK_READY_TIMEOUT ; timeout ++ ) { hw -> phy . ops . read_reg ( hw , IXGBE_MDIO_AUTO_NEG_STATUS , IXGBE_MDIO_AUTO_NEG_DEV_TYPE , & an_reg ) ; if ( ( an_reg & IXGBE_MII_AUTONEG_COMPLETE ) && ( an_reg & IXGBE_MII_AUTONEG_LINK_UP ) ) { break ; } msec_delay ( 100 ) ; } if ( timeout == IXGBE_VALIDATE_LINK_READY_TIMEOUT ) { DEBUGOUT ( "Link was indicated but link is down\n" ) ; return IXGBE_ERR_LINK_SETUP ; } return IXGBE_SUCCESS ; } 